<template><div class="page"><div class="section-title"><div><h2>运维工作台</h2><span class="muted">Minikube 集群与 AutoOps Agent 实时概览</span></div><n-button type="primary" :loading="store.loading" @click="store.refresh">刷新数据</n-button></div><div class="metric-grid"><div class="metric" v-for="m in metrics" :key="m.label"><n-icon :size="28" :color="m.color" :component="m.icon"/><div><div class="metric-value">{{m.value}}</div><div class="metric-label">{{m.label}}</div></div></div></div><div class="dashboard-grid"><div><section class="panel"><div class="section-title"><h3>活跃告警</h3><router-link to="/app/alerts" class="muted">查看全部 →</router-link></div><n-empty v-if="!store.alerts.length" description="当前没有活跃告警"/><n-list v-else hoverable><n-list-item v-for="a in store.alerts.slice(0,6)" :key="a.alert_name"><div><n-tag :type="severityType(a.severity)" size="small">{{a.severity}}</n-tag><strong style="margin-left:10px">{{a.alert_name}}</strong><div class="muted" style="margin-top:5px">{{a.description}}</div></div><span class="muted">{{a.duration}}</span></n-list-item></n-list></section><section class="panel"><div class="section-title"><h3>最近 Events</h3><router-link to="/app/cluster" class="muted">集群观测 →</router-link></div><n-list><n-list-item v-for="e in store.events.slice(-5).reverse()" :key="e.name"><div><n-tag :type="e.type==='Warning'?'warning':'info'" size="small">{{e.type}}</n-tag><span style="margin-left:10px">{{e.reason}} · {{e.object}}</span><div class="muted" style="margin-top:4px">{{e.message}}</div></div></n-list-item></n-list></section></div><div><section class="panel"><div class="section-title"><h3>集群健康</h3><n-tag :type="store.summary?.healthy?'success':'error'">{{store.summary?.healthy?'Healthy':'需要关注'}}</n-tag></div><n-descriptions bordered :column="1" size="small"><n-descriptions-item label="Namespace">{{store.summary?.namespace||'autoops-test'}}</n-descriptions-item><n-descriptions-item label="Pods">{{store.summary?.pods_ready||0}} / {{store.summary?.pods_total||0}} Ready</n-descriptions-item><n-descriptions-item label="Deployments">{{store.summary?.deployments_ready||0}} / {{store.summary?.deployments_total||0}}</n-descriptions-item><n-descriptions-item label="Warning Events">{{store.summary?.events_warning||0}}</n-descriptions-item></n-descriptions></section><section class="panel"><div class="section-title"><h3>Agent 快捷操作</h3></div><div class="quick-actions"><n-button v-for="q in quick" :key="q" secondary @click="ask(q)">{{q}}</n-button></div></section></div></div></div></template>
<script setup>import {computed} from 'vue';import {useRouter} from 'vue-router';import {useDashboardStore} from '@/stores/dashboard';import {WarningOutline,AlertCircleOutline,GitNetworkOutline,BookOutline,CheckmarkCircleOutline} from '@vicons/ionicons5';const router=useRouter(),store=useDashboardStore();const metrics=computed(()=>[{label:'活跃告警',value:store.alerts.length,color:'#d03050',icon:WarningOutline},{label:'Critical',value:store.critical,color:'#d03050',icon:AlertCircleOutline},{label:'Warning',value:store.warning,color:'#f0a020',icon:WarningOutline},{label:'异常 Pods',value:store.unhealthyPods,color:'#d03050',icon:GitNetworkOutline},{label:'健康 Deployments',value:`${store.summary?.deployments_ready||0}/${store.summary?.deployments_total||0}`,color:'#18a058',icon:CheckmarkCircleOutline},{label:'维护文档',value:store.documents.length,color:'#2080f0',icon:BookOutline}]);const quick=['分析当前告警','检查 autoops-test 集群状态','查询最近 Kubernetes Events','查询处理手册'];function severityType(s){return s==='critical'?'error':s==='warning'?'warning':'info'}function ask(q){router.push({path:'/app/chat',query:{prompt:q}})}</script>
